script:
(function () {
  'use strict';
  // Highest purchase price from a monthly housing budget B, for a down payment share d.
  //   Loan L = P x (1 - d). Monthly cost at price P:
  //     cost(P) = L x f + P x tax% / 12 + insurance / 12 + HOA + (d < 20% ? L x pmi% / 12 : 0),
  //     f = i / (1 - (1 + i)^-n), i = rate / 12, n = years x 12 (f = 1 / n at 0%).
  //   cost(P) is linear in P, so P = (B - insurance / 12 - HOA) / ((1 - d) f + tax% / 12 + pmi part).
  //   Cash to close = P x (d + closing%). Best price your cash allows: the largest
  //   min(P(d), cash / (d + closing%)) over down payments from 0% to 95% (0.1% grid, then refined to 0.0005%).
  // Verified in Node (scratchpad b6mtg/pd.test.js): with no tax, insurance, HOA or PMI the price is
  //   B / ((1 - d) f): $2,000 at 6.5% for 30 years and 20% down -> $395,527.05, whose loan of
  //   $316,421.64 has the standard payment of $2,000.00; 0% -> $2,000 x 360 / 0.8 = $900,000;
  //   default example ($2,800, 6.5%, 30 yrs, 10% down, 1.1% tax, $1,800 insurance, 0.5% PMI) ->
  //   $379,641, and the cost at that price re-adds to $2,800.00; PMI drops at 20% down (price jumps);
  //   cash-limited best price ($60,000 cash, 3% closing) -> $388,771 at 12.4% down, an independent
  //   0.01%-step brute-force scan gives $388,759 at 12.43% (its step limit); a budget below
  //   insurance + HOA shows an error; no NaN/Infinity on blank or bad input.
  var LEVELS = [3, 5, 10, 15, 20, 25, 30, 40];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAs) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAs === undefined ? NaN : blankAs;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function factor(annualPct, months) {
    var i = annualPct / 1200;
    return i === 0 ? 1 / months : i / (1 - Math.pow(1 + i, -months));
  }

  // o: budget, f, tax (decimal/yr), ins ($/yr), hoa, pmi (decimal/yr), closing (decimal). d: down share.
  function solve(o, d) {
    var pmiOn = d < 0.2 - 1e-9;
    var room = o.budget - o.ins / 12 - o.hoa;
    var per = (1 - d) * o.f + o.tax / 12 + (pmiOn ? (1 - d) * o.pmi / 12 : 0);
    var P = room > 0 && per > 0 ? room / per : 0;
    var L = P * (1 - d);
    return { d: d, price: P, down: P * d, loan: L, pi: L * o.f, tax: P * o.tax / 12, ins: P > 0 ? o.ins / 12 : 0,
             hoa: P > 0 ? o.hoa : 0, pmi: pmiOn ? L * o.pmi / 12 : 0, cash: P * (d + o.closing) };
  }

  function bestWithCash(o, cash) {
    var best = { price: 0, d: 0 };
    for (var k = 0; k <= 950; k++) {
      var d = k / 1000, p = solve(o, d).price, share = d + o.closing;
      var price = share > 0 ? Math.min(p, cash / share) : p;
      if (price > best.price + 1e-6) best = { price: price, d: d };
    }
    var lo = Math.max(0, best.d - 0.001), hi = Math.min(0.95, best.d + 0.001);
    for (var j = 0; j <= 400; j++) {
      var dd = lo + (hi - lo) * j / 400, pp = solve(o, dd).price, sh = dd + o.closing;
      var pr = sh > 0 ? Math.min(pp, cash / sh) : pp;
      if (pr > best.price + 1e-6) best = { price: pr, d: dd };
    }
    return best;
  }

  function pctText(d) { return (Math.round(d * 1000) / 10) + '%'; }

  function clearResults() {
    ['pdPrice', 'pdDownAmt', 'pdLoan', 'pdBest'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    ['pdPI', 'pdTaxM', 'pdInsM', 'pdPmiM', 'pdHoaM', 'pdTotal', 'pdCashClose'].forEach(function (id) { setText(id, '–'); });
    el('pdShort').hidden = true;
    el('pdTable').innerHTML = '';
  }

  function update() {
    var budget = read('pdBudget'), rate = read('pdRate'), term = read('pdTerm'), down = read('pdDown'),
        cashRaw = String(el('pdCash').value).trim(), cash = read('pdCash', 0), tax = read('pdTax', 0), ins = read('pdIns', 0),
        hoa = read('pdHoa', 0), pmi = read('pdPmi', 0), closing = read('pdClosing', 0);
    var msg = '';
    if (isNaN(budget) || budget <= 0 || budget > 1e7) msg = 'Enter a monthly housing budget greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(term) || term < 1 || term > 40 || term % 1 !== 0) msg = 'Enter a loan term of 1 to 40 whole years.';
    else if (isNaN(down) || down < 0 || down > 95) msg = 'Enter a down payment from 0% to 95%.';
    else if (isNaN(cash) || cash < 0 || cash > 1e9) msg = 'Enter cash available of $0 or more, or leave it blank.';
    else if (isNaN(tax) || tax < 0 || tax > 10) msg = 'Enter a property tax rate from 0% to 10%.';
    else if (isNaN(ins) || ins < 0 || ins > 1e6 || isNaN(hoa) || hoa < 0 || hoa > 1e5) msg = 'Enter insurance and HOA dues of $0 or more.';
    else if (isNaN(pmi) || pmi < 0 || pmi > 5) msg = 'Enter a PMI rate from 0% to 5%.';
    else if (isNaN(closing) || closing < 0 || closing > 15) msg = 'Enter closing costs from 0% to 15%.';
    else if (budget <= ins / 12 + hoa) msg = 'Your budget does not cover insurance and HOA dues of ' + money.format(ins / 12 + hoa) + ' a month, so it leaves nothing for the loan.';
    var error = el('pdError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var o = { budget: budget, f: factor(rate, term * 12), tax: tax / 100, ins: ins, hoa: hoa, pmi: pmi / 100, closing: closing / 100 };
    var r = solve(o, down / 100);
    setText('pdPrice', money0.format(r.price));
    setText('pdPriceNote', 'With ' + pctText(r.d) + ' down and a ' + money0.format(budget) + ' monthly budget.');
    setText('pdDownAmt', money0.format(r.down));
    setText('pdDownAmtNote', 'Plus about ' + money0.format(r.price * o.closing) + ' in closing costs.');
    setText('pdLoan', money0.format(r.loan));
    setText('pdLoanNote', term + '-year loan at ' + rate + '%.');
    var hasCash = cashRaw !== '' && cash > 0;
    if (hasCash) {
      var b = bestWithCash(o, cash);
      setText('pdBest', money0.format(b.price));
      setText('pdBestNote', 'Putting about ' + pctText(b.d) + ' down, the mix where ' + money0.format(cash) + ' covers the down payment and closing costs and the payment stays within budget.');
    } else {
      setText('pdBest', '–');
      setText('pdBestNote', 'Enter the cash you have to see the best mix.');
    }
    setText('pdPI', money.format(r.pi));
    setText('pdTaxM', money.format(r.tax));
    setText('pdInsM', money.format(r.ins));
    setText('pdPmiM', money.format(r.pmi));
    setText('pdHoaM', money.format(r.hoa));
    setText('pdTotal', money.format(r.pi + r.tax + r.ins + r.pmi + r.hoa));
    setText('pdCashClose', money.format(r.cash));
    var short = el('pdShort');
    short.hidden = !(hasCash && cash < r.cash - 0.005);
    if (!short.hidden) setText('pdShortText', 'You need about ' + money0.format(r.cash) + ' to close at this price, ' + money0.format(r.cash - cash) + ' more than you have. Use the best-price figure above or the table below to find a down payment your cash covers.');

    var levels = LEVELS.slice();
    if (levels.indexOf(down) < 0) levels.push(down);
    levels.sort(function (a, c) { return a - c; });
    el('pdTable').innerHTML = levels.map(function (lv) {
      var x = solve(o, lv / 100);
      var fits = !hasCash ? '–' : (cash >= x.cash - 0.005 ? 'Yes' : 'No, short ' + money0.format(x.cash - cash));
      return '<tr><td>' + pctText(lv / 100) + (lv === down ? ' (yours)' : '') + '</td><td>' + money0.format(x.price) + '</td><td>' + money0.format(x.down) + '</td><td>' +
        money0.format(x.loan) + '</td><td>' + money.format(x.pi) + '</td><td>' + money.format(x.pmi) + '</td><td>' + money0.format(x.cash) + '</td><td>' + fits + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('pdForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
